-- L14596/O44 环境漂移垫片(仅 ihui_dev,2026-10-18):
-- drizzle journal 第 325 枚 20261018160000_agent_state_tables_runtime_reality 在本库
-- 卡在 line 111 `ALTER TABLE "agent_federated_lessons" ALTER COLUMN "id" TYPE bigint`,
-- 因 ihui_dev 该列是漂移形态 uuid DEFAULT gen_random_uuid(),默认值无法自动投到 bigint;
-- 权威形态以 packages/database/src/schema/agent-state.ts(bigserial)与 ihui 库现状
-- (bigint + nextval('agent_federated_lessons_id_seq'))为准。本表 0 行,转换零数据风险。
-- 本垫片先收敛列形态,再原样重放第 325 枚迁移;迁移文件本身一字不改(hash 对账不受影响)。

ALTER TABLE "agent_federated_lessons" ALTER COLUMN "id" DROP DEFAULT;
ALTER TABLE "agent_federated_lessons" ALTER COLUMN "id" TYPE bigint USING "id"::text::bigint;
CREATE SEQUENCE IF NOT EXISTS "agent_federated_lessons_id_seq" OWNED BY "agent_federated_lessons"."id";
SELECT setval('agent_federated_lessons_id_seq', GREATEST((SELECT COALESCE(MAX("id"),0) FROM "agent_federated_lessons"), 1));
ALTER TABLE "agent_federated_lessons" ALTER COLUMN "id" SET DEFAULT nextval('agent_federated_lessons_id_seq');
